import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.YT-FC_Xx.js";const c=JSON.parse('{"title":"隧道与转发规则","description":"","frontmatter":{},"headers":[],"relativePath":"guide/forward.md","filePath":"guide/forward.md","lastUpdated":1794059590000}'),n={name:"guide/forward.md"};function l(s,t,d,i,g,h){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="隧道与转发规则" tabindex="-1">隧道与转发规则 <a class="header-anchor" href="#隧道与转发规则" aria-label="Permalink to &quot;隧道与转发规则&quot;">​</a></h1><p>面板保留了原来转发面板的隧道和转发规则。只做落地 + 中转的话，用 <a href="./relay">对接中转</a> 就够了，面板会自动建好需要的转发规则；需要自己管理端口转发时再看这一页。</p><p>FLYX 是单用户面板：只有管理员一个账号，没有多用户、用户配额、限速和流量计费。</p><h2 id="隧道" tabindex="-1">隧道 <a class="header-anchor" href="#隧道" aria-label="Permalink to &quot;隧道&quot;">​</a></h2><p><strong>中转 → 隧道</strong>：从入口服务器到出口的转发线路，转发规则建在隧道上。</p><table tabindex="0"><thead><tr><th>设置</th><th>说明</th></tr></thead><tbody><tr><td>隧道类型</td><td><strong>端口转发</strong>：入口服务器直接转发到目标；<strong>隧道转发</strong>：入口经加密隧道到出口服务器，再由出口转发（入口和出口不能是同一台服务器）</td></tr><tr><td>入口服务器</td><td>可以多选；多台服务器时可选 <strong>负载策略</strong></td></tr><tr><td>协议</td><td>隧道转发时入口和出口之间用的协议；只要中转、不需要加密时选 TCP</td></tr><tr><td>转发引擎</td><td>端口转发时可选。<strong>面板转发</strong>（默认）：agent 直接转发；<strong>realm</strong>：入口服务器自动安装 <a href="https://github.com/zhboner/realm" target="_blank" rel="noreferrer">realm</a> 来跑这条隧道的转发</td></tr></tbody></table><p>隧道卡片上的 <strong>诊断</strong> 可以检查入口到出口是否连通。</p><p>规则的流量按实际上传和下载字节统计，面板转发、realm 和 nftables 都一样。旧版本隧道上设置的计费方向和流量倍率不再生效，保存隧道时会被清除。</p><h3 id="realm-引擎" tabindex="-1">realm 引擎 <a class="header-anchor" href="#realm-引擎" aria-label="Permalink to &quot;realm 引擎&quot;">​</a></h3><p>realm 是 Rust 写的端口转发程序，占用低，适合流量大的纯端口转发。选了 realm 的隧道：</p><ul><li>入口服务器上的 realm 由面板安装和管理（<strong>入站 → 内核</strong> 里能看到“realm（转发引擎）”，可查看日志），agent 需要升级到支持 realm 的版本</li><li>转发规则照常建，TCP / UDP、多个目标负载（轮询或 IP 哈希，主备和随机按轮询处理）、Proxy Protocol 都支持；流量照常统计，暂停也照常生效</li><li>不能用于 nftables 模式服务器和远程服务器</li></ul><p>随时可以在编辑隧道时切换引擎，面板会把已有的转发规则迁移过去。</p><h2 id="转发规则" tabindex="-1">转发规则 <a class="header-anchor" href="#转发规则" aria-label="Permalink to &quot;转发规则&quot;">​</a></h2><p><strong>规则</strong> 页（或 <strong>中转 → 规则</strong>）：把入口端口收到的流量经隧道转发到目标地址。</p><ul><li>选 <strong>所属隧道</strong>，填 <strong>落地地址</strong>（目标地址和端口），入口端口留空自动分配</li><li>支持 TCP / UDP</li><li>高级设置里可以开启 <strong>Proxy Protocol 发送 / 接收</strong>，让目标看到客户端真实 IP</li><li>支持批量导入导出</li></ul><p>旧版本规则上设置的限速、最大连接数和每 IP 限制不再下发到服务器；节点上留下的限速器会在下次同步配置时清理，编辑保存规则时这些旧值也会被清除。</p><h2 id="监控" tabindex="-1">监控 <a class="header-anchor" href="#监控" aria-label="Permalink to &quot;监控&quot;">​</a></h2><p>监控已并入 <strong>服务器</strong> 和 <strong>中转</strong>：</p><ul><li><strong>服务器</strong> 列表（和卡片）上直接显示每台服务器的 CPU、内存、磁盘、实时网速和本月流量；点服务器再点 <strong>监控</strong>，看这台服务器的历史曲线和服务监控。本月流量从升级到这个版本后开始累计，按浏览器所在时区从每月 1 号算起</li><li><strong>中转 → 质量</strong>：隧道的延迟和丢包</li></ul><p>节点历史的新记录按 15 分钟汇总；半小时、45 分钟时区的月初边界可正确划分。跨月的旧小时记录只能按时长估算，相关提示会显示在本月流量的说明中。</p><p>节点流量汇总仍保留 400 天，不因粒度变化缩短历史。连续采集时，每个节点每天的汇总记录由 24 条增至 96 条，400 天约 38,400 条；汇总表及其索引的存储需求会随记录数增长，实际占用取决于采集情况和数据库。这不表示整个数据库会增大四倍，升级前应按节点数量预留空间。</p><p>监控明细的保留天数在 <strong>设置 → 服务器与监控</strong> 里设置，不影响上述流量汇总的 400 天保留期。服务器到各地运营商的延迟见 <a href="./latency">延迟与回程</a>。</p><h2 id="共享" tabindex="-1">共享 <a class="header-anchor" href="#共享" aria-label="Permalink to &quot;共享&quot;">​</a></h2><p><strong>共享</strong> 页：把本地服务器分享给其他 FLYX 面板，或导入别人分享的服务器，两个面板可以互相使用对方的服务器做转发。</p>',24)])])}const m=r(n,[["render",l]]);export{c as __pageData,m as default};
